var poemLines = [
  { line: "Cigarette ash in a coffee cup moon", mood: "loneliness" },
  { line: "She left her shoes and a sad old tune", mood: "nostalgia" },
  { line: "The jukebox coughs up ghosts and gin", mood: "mystery" },
  { line: "While midnight hangs on a violin", mood: "melancholy" },
  { line: "The rain taps Morse code on the glass", mood: "grief" },
  { line: "Each drop a name from a buried past", mood: "grief" },
  { line: "Neon sighs through a bottle’s glare", mood: "despair" },
  { line: "Whiskey prayers and nicotine air", mood: "loneliness" },
  { line: "He sings for dimes with rusted chords", mood: "hope" },
  { line: "And stitches time with busted words", mood: "wonder" }
];

var osc, env;
var currentIndex = 0;
var currentLine = 0;
var boxSize;
var lineHeight;

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  userStartAudio();

  osc = new p5.Oscillator('sine');
  env = new p5.Envelope();
  env.setADSR(0.01, 0.2, 0.1, 0.4);
  env.setRange(0.3, 0);
  osc.start();
  osc.amp(0);

  lineHeight = height / poemLines.length;
  const longest = Math.max(...poemLines.map(p => p.line.length));
  boxSize = width / longest;

  frameRate(8); // adjust tempo
}

function draw() {
  const { line, mood } = poemLines[currentLine];
  const moodData = moodPalettes[mood] || moodPalettes["joy"];

  if (!moodPalettes[mood]) {
    console.warn(`Missing palette/scale for mood: ${mood}`);
  }

  const { palette, scale } = moodData;

  if (currentIndex < line.length) {
    const char = line[currentIndex];
    const x = currentIndex * boxSize;
    const y = currentLine * lineHeight;
    const colorIndex = currentIndex % palette.length;
    fill(palette[colorIndex]);
    rect(x, y, boxSize, lineHeight);
    playNoteFromChar(char, scale);
    currentIndex++;
  } else {
    currentIndex = 0;
    currentLine++;
    if (currentLine >= poemLines.length) {
      // noLoop() removed for animation
    }
  }
}

function playNoteFromChar(char, scale) {
  const upper = char.toUpperCase();
  if (upper < "A" || upper > "Z") return;

  const index = upper.charCodeAt(0) - 65;
  const note = scale[index % scale.length];
  const freq = midiToFreq(noteToMidi(note));
  osc.freq(freq);
  env.play(osc);
}

function noteToMidi(note) {
  const noteMap = {
    "C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11,
    "Ab": 8, "Bb": 10, "Eb": 3, "F#": 6
  };
  let name = note.slice(0, note.length - 1);
  let octave = parseInt(note[note.length - 1]);
  return 12 * (octave + 1) + noteMap[name];
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  redraw();
}
